"""Give animals a model generated by Scenario (Meshy 7.1 image-to-3D from the concept image) instead of the built-in
lofted one. Safe to run again. Run in the editor, outside Play:
    UnrealEditor.exe EW.uproject -ExecCmds="py <this file>"
For every entry in GENERATED whose .glb is in Art/Animals/Generated, this imports it (textures, material, mesh) to
/Game/Elitewake/Wildlife/Animals/Generated/<Name>, turns it to face +X, scales it to the length wanted and stands its feet
on the ground, and sets all of that on the animal's definition. The generated models are centred and face along Y.
Provenance: Art/Animals/Generated/PROMPTS.md.
A generated model is one rigid mesh: it moves, turns and bobs with the animal but its legs do not stride."""
import unreal
from pathlib import Path

ROOT = Path(unreal.Paths.project_dir())
SOURCE = ROOT / 'Art/Animals/Generated'
FOLDER = '/Game/Elitewake/Wildlife/Animals/Generated'
DEF = '/Game/Elitewake/Wildlife/Animals/DA_Animal_'
# name: (yaw to face +X, length wanted in cm). Lengths are tuning: a lion nose to rump, a bear, a giant crocodile
# (owner: giant, exact scale undecided) and an elephant trunk tip to rump.
GENERATED = {
    'Lion': (-90.0, 240.0),
    'Bear': (-90.0, 190.0),
    'GiantCrocodile': (-90.0, 600.0),
    'Elephant': (-90.0, 380.0),
}


def import_mesh(name, filename):
    task = unreal.AssetImportTask()
    for k, v in {'filename': str(filename), 'destination_path': f'{FOLDER}/{name}', 'automated': True,
                 'replace_existing': True, 'save': True}.items():
        task.set_editor_property(k, v)
    unreal.AssetToolsHelpers.get_asset_tools().import_asset_tasks([task])
    mesh = unreal.load_asset(f'{FOLDER}/{name}/{name}/StaticMeshes/{name}.{name}')
    assert isinstance(mesh, unreal.StaticMesh), name
    return mesh


def main():
    for name, (yaw, length) in GENERATED.items():
        source = SOURCE / f'{name}.glb'
        if not source.is_file():
            unreal.log_warning(f'{name}: no {source}, left as it was')
            continue
        mesh = import_mesh(name, source)
        box = mesh.get_bounding_box()
        scale = length / (box.max.y - box.min.y)
        definition = unreal.load_asset(DEF + name)
        assert definition, name
        definition.set_editor_property('mesh', mesh)
        definition.set_editor_property('mesh_rotation', unreal.Rotator(0, 0, yaw))   # Rotator(roll, pitch, yaw)
        definition.set_editor_property('mesh_scale', scale)
        definition.set_editor_property('mesh_foot_lift', -box.min.z * scale)
        assert unreal.EditorAssetLibrary.save_loaded_asset(definition)
        unreal.log(f'{name}: generated mesh applied, scale {scale:.2f}, {box.max.z - box.min.z:.0f} cm tall before scaling')


if __name__ == '__main__':
    main()
